import React from 'react';
import Prompts from './Prompts';
import { apiRequest } from '../api';

type Prompt = {
  id: number;
  name: string;
  description: string;
  category: string;
  is_active: boolean;
  is_base: boolean;
  can_work_alone?: boolean;
  icon_color?: string;
  icon_emoji?: string;
  locale?: string;
  key?: string;
  features?: string;
  target_audience?: string;
  activation_triggers?: string;
  kind?: string;
  sort_order?: number;
  usage_count?: number;
  rating?: number;
  created_at?: string;
  updated_at?: string;
  disable_base_personality?: boolean;
  deep_memory_only?: boolean;
};

const PromptsStandalone: React.FC = () => {
  const [prompts, setPrompts] = React.useState<Prompt[]>([]);
  const [selectedPrompt, setSelectedPrompt] = React.useState<Prompt | null>(null);
  const [disableBasePersonality, setDisableBasePersonality] = React.useState(false);
  const [loading, setLoading] = React.useState(true);

  const load = React.useCallback(async () => {
    try {
      const tgId = (() => { try { return sessionStorage.getItem('tg_id'); } catch { return null; } })();
      if (!tgId) { setLoading(false); return; }
      const res = await apiRequest('/miniapp/prompts', 'GET', null, { 'X-Telegram-User-ID': String(tgId) });
      const items: Prompt[] = res.items || [];
      setPrompts(items);
      const active = items.find(p => p.is_active) || items.find(p => p.key === 'prompt-4') || null;
      if (active) {
        setSelectedPrompt(active);
        setDisableBasePersonality(!!active.disable_base_personality);
      }
    } finally {
      setLoading(false);
    }
  }, []);

  React.useEffect(() => { load(); }, [load]);

  const onPromptSelect = (p: Prompt) => setSelectedPrompt(p);

  const onSetActivePersonality = async (promptKey: string, disableBase?: boolean) => {
    try {
      const tgId = sessionStorage.getItem('tg_id');
      if (!tgId) throw new Error('Unauthorized');
      const form = new FormData();
      form.append('prompt_key', promptKey);
      if (typeof disableBase === 'boolean') form.append('disable_base', String(disableBase));
      const resp = await fetch('/api/miniapp/prompts/set-active', { method: 'POST', body: form, headers: { 'X-Telegram-User-ID': String(tgId) } });
      if (resp.ok) {
        const data = await resp.json();
        setDisableBasePersonality(!!data.disable_base_personality);
        await load();
      }
    } catch {}
  };

  const onPromptStatusChange = async (promptId: number, newStatus: boolean) => {
    const p = prompts.find(px => px.id === promptId);
    if (!p || !p.key) return;
    await onSetActivePersonality(newStatus ? p.key : 'prompt-4');
  };

  const onDisableBasePersonalityChange = async (checked: boolean) => {
    try {
      const tgId = sessionStorage.getItem('tg_id');
      if (!tgId) throw new Error('Unauthorized');
      const form = new FormData();
      form.append('disable_base', String(checked));
      const resp = await fetch('/api/miniapp/prompts/update-settings', { method: 'POST', body: form, headers: { 'X-Telegram-User-ID': String(tgId) } });
      if (resp.ok) setDisableBasePersonality(checked);
    } catch {}
  };

  if (loading) return <div className="screen loading"><div className="spinner" /></div>;

  return (
    <Prompts
      prompts={prompts}
      selectedPrompt={selectedPrompt}
      onPromptSelect={onPromptSelect}
      onPromptStatusChange={onPromptStatusChange}
      onSetActivePersonality={onSetActivePersonality}
      disableBasePersonality={disableBasePersonality}
      onDisableBasePersonalityChange={onDisableBasePersonalityChange}
    />
  );
};

export default PromptsStandalone;


